package com.shipflow.warehouse.application;import com.shipflow.order.domain.model.ShipmentOrder;import com.shipflow.warehouse.api.model.*;import com.shipflow.warehouse.domain.WarehouseChargeableWeight;import com.shipflow.warehouse.mapper.WarehouseMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;
@Service public class WarehouseApplicationService{private final WarehouseMapper m;private final Clock clock;public WarehouseApplicationService(WarehouseMapper m,Clock c){this.m=m;clock=c;}@Transactional public WarehouseResult inbound(Long t,Long u,Long id,InboundRequest r,String req){ShipmentOrder o=require(t,id);transition(t,id,"PENDING_INBOUND","INBOUND",r.version(),"WAREHOUSE-1001");audit(t,u,id,"INBOUND",req);return result(require(t,id));}@Transactional public WarehouseResult measure(Long t,Long u,Long id,MeasurementRequest r,String req){ShipmentOrder o=require(t,id);if(!"INBOUND".equals(o.currentStatus()))throw new WarehouseException("WAREHOUSE-1002",409);Long p=m.packageId(t,id);if(p==null)throw new WarehouseException("COMMON-1006",404);BigDecimal divisor=new BigDecimal("5000"),inc=new BigDecimal("0.5"),v=r.actualLength().multiply(r.actualWidth()).multiply(r.actualHeight()).divide(divisor,3,RoundingMode.HALF_UP),cw;try{cw=WarehouseChargeableWeight.calculate(r.actualWeight(),r.actualLength(),r.actualWidth(),r.actualHeight(),divisor,inc);}catch(Exception e){throw new WarehouseException("WAREHOUSE-1002",422);}LocalDateTime now=LocalDateTime.now(clock);m.insertMeasurement(t,p,r.actualWeight(),r.actualLength(),r.actualWidth(),r.actualHeight(),v,cw,u,now);BigDecimal after=o.estimatedFee().multiply(cw).divide(o.chargeableWeight(),2,RoundingMode.HALF_UP);String status=after.compareTo(o.currentFee())>0?"PENDING_PRICE_CONFIRMATION":"READY_FOR_OUTBOUND";if(after.compareTo(o.currentFee())!=0){Long mid=m.latestMeasurementId(t,p);m.insertAdjustment(t,id,mid,after.compareTo(o.currentFee())>0?"INCREASE":"DECREASE",o.currentFee(),after,after.subtract(o.currentFee()),o.currency());}m.updateFee(t,id,cw,after,status);audit(t,u,id,"MEASURE",req);return result(require(t,id));}@Transactional public WarehouseResult outbound(Long t,Long u,Long id,OutboundRequest r,String req){ShipmentOrder o=require(t,id);if(!"READY_FOR_OUTBOUND".equals(o.currentStatus()))throw new WarehouseException("WAREHOUSE-1004",409);Long p=m.packageId(t,id);try{m.outbound(t,id,p,r.trackingNo(),u,LocalDateTime.now(clock),r.remark());}catch(org.springframework.dao.DuplicateKeyException e){throw new WarehouseException("WAREHOUSE-1005",409);}transition(t,id,"READY_FOR_OUTBOUND","OUTBOUND",r.version(),"WAREHOUSE-1004");audit(t,u,id,"OUTBOUND",req);return result(require(t,id));}private ShipmentOrder require(Long t,Long i){var o=m.findOrder(t,i);if(o==null)throw new WarehouseException("COMMON-1006",404);return o;}private void transition(Long t,Long i,String f,String to,Long v,String code){if(m.transition(t,i,f,to,v)!=1)throw new WarehouseException(code,409);}private void audit(Long t,Long u,Long i,String a,String r){m.audit(t,u,i,a,r,LocalDateTime.now(clock));}private WarehouseResult result(ShipmentOrder o){return new WarehouseResult(o.id(),o.currentStatus(),o.chargeableWeight(),o.estimatedFee());}}
